# Recalculate 8 positions in each region with local coordinates
hr_starts = [0, 5, 10]  # row starts for horizontal regions
vr_col_offsets = [0, 3, 6, 9, 12]  # column offsets for vertical regions

eights = [(r, c) for r in range(14) for c in range(14) if grids[r][c] == 8]

print("\n=== 8 positions in LOCAL region coordinates ===\n")

for h, rows_start in enumerate(hr_starts):
    for v, col_offset in enumerate(vr_col_offsets):
        local_8s = []
        for (r, c) in eights:
            if rows_start <= r < rows_start + 4:
                local_col = c - col_offset
                if 0 <= local_col < 2:
                    local_8s.append((r - rows_start, local_col))
        if local_8s:
            print(f"Region ({h},{v}) local coords 4x2:")
            for local_r, local_c in local_8s:
                print(f"  ({local_r}, {local_c})")
            print()

# Count how many 8s in each region
print("\n=== COUNT OF 8s per region ===")
for h, rows_start in enumerate(hr_starts):
    for v, col_offset in enumerate(vr_col_offsets):
        cnt = sum(1 for (r, c) in eights if rows_start <= r < rows_start + 4 and col_offset <= c < col_offset + 2)
        print(f"Region ({h},{v}): {cnt} eights", end="")
        if cnt > 1:
            print(" (multiple)")
        else:
            print()

